using namespace Snatcher;
namespace {
unsigned checks=0;std::string error;
void check(bool ok,const char* why){++checks;if(!ok){std::cerr<<"Layer publication: "<<why<<": "<<error<<"\n";std::exit(1);}}
void word(std::vector<uint8_t>& b,size_t at,unsigned v){b[at]=uint8_t(v>>8);b[at+1]=uint8_t(v);}
void longword(std::vector<uint8_t>& b,size_t at,unsigned v){word(b,at,v>>16);word(b,at+2,v);}
struct Source:SceneStateSource {
 std::vector<uint8_t> bytes;
 Source():bytes(4096,0){longword(bytes,0,0x28008);longword(bytes,4,0x28020);word(bytes,32,2);bytes[34]=0x80;}
 bool loadSceneResource(uint16_t id,std::vector<uint8_t>& out,std::string&)override{if(id!=22)return false;out=bytes;return true;}
};
std::vector<uint16_t> colors(){std::vector<uint16_t> p(128,0);p[1]=0xeee;p[2]=0x00e;p[3]=0x0e0;p[4]=0xe00;p[5]=0xee0;p[6]=0xe0e;p[7]=0x0ee;return p;}
GraphicsTransfer tiles(){GraphicsTransfer pattern;pattern.destination=32;pattern.decoded.assign(128,0);for(unsigned y=0;y<8;++y){pattern.decoded[y*4]=0x12;pattern.decoded[y*4+1]=0x34;pattern.decoded[y*4+2]=0x12;pattern.decoded[y*4+3]=0x34;}for(unsigned i=32;i<64;++i)pattern.decoded[i]=0x55;for(unsigned i=64;i<96;++i)pattern.decoded[i]=0x66;for(unsigned i=96;i<128;++i)pattern.decoded[i]=0x77;
return pattern;}
SceneRuntime world(Source& source){SceneRuntime scene;SceneLayout layout;layout.width=256;layout.height=224;layout.columns=32;layout.rows=64;
 check(scene.configure(layout,error)&&scene.establishSceneReset(kSceneSquareLayout,error)&&scene.establishSceneReset(kSceneTallLayout,error),"square license reset establishes all rows before partial tall reset");scene.establishBlankAssets();scene.establishFreshModuleDialogueContext();scene.establishFreshAnimationClock();scene.establishSceneFlags(0);
 check(scene.setPalette(colors(),0,error)&&scene.install(22,source.bytes,0,error),"source-bound scene and palette");auto pattern=tiles();
 check(scene.applyTransfer(pattern,error)&&scene.fillPlaneCells(0,0,0,32,64,0,error)&&scene.fillPlaneCells(1,0,0,32,64,1,error)&&scene.fillPlaneCells(0,10,1,1,17,0x8002,error)&&scene.fillPlaneCells(0,0,32,32,32,0x8002,error),"nontrivial two-plane source-format maps");
 std::vector<PlacedPiece> pieces={{40,40,8,8,3},{40,40,8,8,0x8004}};check(scene.setMenuCursorPieces(pieces,error)&&scene.requestVisualCommand(15,error),"primary caption and ordered low/high sprites");
 check(scene.queueAbsolutePlanePosition(0,5,0,error)&&scene.queueAbsolutePlanePosition(1,11,0,error)&&scene.updateObjects(false,error)&&scene.commitEnvironmentFrame(0,error)&&scene.commitEnvironmentFrame(0,error)&&scene.beginFrame(false,error,1),"published full-plane pair before line mode");return scene;
}
unsigned wrap(int value,unsigned width){int v=value%int(width);return unsigned(v<0?v+int(width):v);}
void exact(SceneRuntime& scene,bool line,int a,int b,int first,int second,bool legacy=false,int third=0,int fourth=0,bool tailKnown=true,bool mode5=false,bool partialRows=false,bool mode6=false,bool retainedTail=false){SceneImage image;check(scene.render(kSceneReferenceRGB565,image,error)&&image.width==256&&image.height==224,"complete canonical raster");auto palette=colors();std::vector<uint8_t> indexed(256*224),rgb(256*224*3);uint8_t channels[8][3];for(unsigned c=0;c<8;++c)check(sceneColor(palette[c],kSceneReferenceRGB565,channels[c][0],channels[c][1],channels[c][2],error),"canonical color domain");
 for(unsigned y=0;y<224;++y)for(unsigned x=0;x<256;++x){int ax=a,bx=b;int sample=y>=8&&y<16?first:y>=16&&y<25?second:y>=37&&y<47?third:y>=66&&y<70?fourth:0;if(mode5)sample=y>=56&&y<59?8:y>=59&&y<61?12:y>=61&&y<64?8:y>=80&&y<104?1022:y>=104&&y<120?1020:0;if(mode6)sample=y>=120&&y<129?2:y>=129&&y<136?1022:0;if(retainedTail)sample=y==128?2:y>=129&&y<136?1022:0;if(line){if(legacy)bx+=sample;else{ax=y&&(!partialRows||y<128)?0:a;bx=y?(y>=8&&y<136?(partialRows&&y>=128&&!tailKnown?b:sample):(partialRows&&y>=128?b:0)):b;}}
  unsigned sy=y+(y>=144?256:0),sx=wrap(int(x)+ax,256);uint8_t color=uint8_t(1+wrap(int(x)+bx,4));if(x>=40&&x<48&&y>=40&&y<48)color=6;if(sy>=256||(sy>=8&&sy<144&&sx>=80&&sx<88))color=5;size_t at=y*256+x;indexed[at]=color;for(unsigned c=0;c<3;++c)rgb[at*3+c]=channels[color][c];}
 if(image.indexed!=indexed||image.rgb!=rgb){size_t different=0,firstAt=0;for(size_t i=0;i<indexed.size();++i)if(image.indexed[i]!=indexed[i]){if(!different)firstAt=i;++different;}std::fprintf(stderr,"fixture=%u line=%u legacy=%u different=%zu first=(%zu,%zu) actual=%u expected=%u ax=%d bx=%d firstBand=%d secondBand=%d\n",checks,unsigned(line),unsigned(legacy),different,firstAt%256,firstAt/256,unsigned(image.indexed[firstAt]),unsigned(indexed[firstAt]),a,b,first,second);}
 check(image.indexed==indexed&&image.rgb==rgb,"zero differing indexed/canonical pixels across full256x224 layers");}
void contracts(){
 // This fixture owns two displayed and two pending pieces. Later schemas add
 // 5+2*19+2 submission bytes,6 menu bytes,4 empty-copy bytes,1 clear and2 mode bytes.
 const size_t publicationTail=1+5+2*19+2+6+4+1+2+5;
 Source source;auto scene=world(source);exact(scene,false,-5,-11,0,0);
 check(scene.requestVisualCommand(3,error)&&scene.beginFrame(false,error,2),"new worker initializes after prior publication");exact(scene,false,-5,-11,0,0);
 check(scene.queueScrollPosition(1,kScrollX,7,error)&&scene.updateObjects(false,error)&&scene.scroll().positions[1].x16==11*65536&&scene.scroll().pending[1].x16==7*65536,"line request disables ordinary producer without deleting pending displacement");
 check(scene.beginFrame(false,error,4),"first worker computation follows zero publication");exact(scene,true,-5,-11,0,0);
 check(scene.beginFrame(false,error,6),"previous computed rows publish");exact(scene,true,-5,-11,1,1);
 check(scene.requestVisualCommand(2,error)&&scene.updateObjects(false,error)&&scene.scroll().positions[1].x16==18*65536&&scene.beginFrame(false,error,8),"full-plane selection preserves hidden line worker");exact(scene,true,-5,-11,2,1);
 check(scene.beginFrame(false,error,10),"full-plane row-zero publication follows selection");exact(scene,false,-5,-18,0,0);
 check(scene.requestVisualCommand(3,error)&&scene.beginFrame(false,error,12),"new worker retains prior full-plane sampling until publication");exact(scene,false,-5,-18,0,0);
 check(scene.beginFrame(false,error,14),"new zero CPU rows replace retained rows");exact(scene,true,-5,-18,0,0);
 check(scene.beginFrame(false,error,16),"new worker computed prefix publishes");exact(scene,true,-5,-18,1,0);
 NativeSaveSection saved;check(SceneStateCodec::encode(scene,saved,error)&&saved.bytes[3]=='T',"SNST retains computed and displayed row owners");SceneRuntime loaded;check(SceneStateCodec::decode(saved,source,loaded,error),"actual codec reconstructs row ownership");exact(loaded,true,-5,-18,1,0);
 auto broken=saved;broken.bytes[broken.bytes.size()-publicationTail-1031]=0;NativeSaveSection before,after;check(SceneStateCodec::encode(loaded,before,error)&&!SceneStateCodec::decode(broken,source,loaded,error)&&SceneStateCodec::encode(loaded,after,error)&&before.bytes==after.bytes,"unknown row history cannot acquire nonzero inherited rows");
 auto oldL=saved;oldL.bytes[3]='L';oldL.bytes.resize(oldL.bytes.size()-publicationTail-2);check(SceneStateCodec::decode(oldL,source,loaded,error),"SNSL retains its partial-row compatibility policy");exact(loaded,true,-5,-18,1,0,false,0,0,true,false,true);check(SceneStateCodec::encode(loaded,after,error)&&after.bytes[3]=='T',"SNSL compatibility provenance survives new archive");
 auto invalid=saved;invalid.bytes[invalid.bytes.size()-publicationTail-1]=1;check(!SceneStateCodec::decode(invalid,source,loaded,error),"complete rows cannot carry contradictory legacy unknown provenance");
 SceneRuntime unknown;SceneLayout plain;plain.width=256;plain.height=224;plain.columns=32;plain.rows=64;check(unknown.configure(plain,error)&&unknown.establishSceneReset(kSceneTallLayout,error),"partial reset without license does not fabricate later rows");unknown.establishFreshModuleDialogueContext();check(unknown.requestVisualCommand(3,error)&&unknown.beginFrame(false,error,1)&&unknown.beginFrame(false,error,2),"partial row owner accepts source selector and publication");SceneImage unavailable;check(!unknown.render(kSceneReferenceRGB565,unavailable,error)&&unavailable.rgb.empty(),"new unknown source row history has explicit guard, no approximate raster");
 auto old=saved;old.bytes[3]='K';old.bytes.resize(old.bytes.size()-publicationTail-1033);check(SceneStateCodec::decode(old,source,loaded,error),"legacy SNSK shape remains readable");exact(loaded,true,-5,-18,2,1,true,1,1);check(SceneStateCodec::encode(loaded,after,error)&&after.bytes[3]=='T',"legacy composition provenance survives new save");
 check(scene.requestVisualCommand(0xfd,error)&&scene.secondaryScrollFrozen()&&scene.requestVisualCommand(2,error)&&scene.secondaryScrollFrozen(),"full-plane request does not retire frozen worker");exact(scene,true,-5,-18,1,0);check(scene.beginFrame(false,error,18),"full-plane selector consumes after final line publication");exact(scene,true,-5,-18,2,1,false,1,1);
 check(scene.requestVisualCommand(3,error)&&!scene.secondaryScrollFrozen()&&scene.beginFrame(false,error,20),"new line selector restarts frozen worker");exact(scene,false,-5,-18,0,0);
 auto phase6=world(source);check(phase6.requestVisualCommand(6,error)&&phase6.beginFrame(false,error,1)&&phase6.beginFrame(false,error,2)&&phase6.beginFrame(false,error,3),"mode6 establishes nonzero later B rows from actual prefix");exact(phase6,true,-5,-11,0,0,false,0,0,true,false,false,true);
 phase6.resetForModule();SceneLayout tall;tall.width=256;tall.height=224;tall.columns=32;tall.rows=64;check(phase6.configure(tall,error)&&phase6.establishSceneReset(kSceneTallLayout,error),"module reset preserves displayed later rows before partial source clear");phase6.establishBlankAssets();phase6.establishFreshAnimationClock();phase6.establishFreshModuleDialogueContext();phase6.establishSceneFlags(0);check(phase6.setPalette(colors(),0,error)&&phase6.install(22,source.bytes,0,error)&&phase6.applyTransfer(tiles(),error)&&phase6.fillPlaneCells(0,0,0,32,64,0,error)&&phase6.fillPlaneCells(1,0,0,32,64,1,error)&&phase6.fillPlaneCells(0,10,1,1,17,0x8002,error)&&phase6.fillPlaneCells(0,0,32,32,32,0x8002,error),"new module source assets after real partial reset");std::vector<PlacedPiece> sprites={{40,40,8,8,3},{40,40,8,8,0x8004}};check(phase6.setMenuCursorPieces(sprites,error)&&phase6.requestVisualCommand(15,error)&&phase6.queueAbsolutePlanePosition(0,5,0,error)&&phase6.queueAbsolutePlanePosition(1,11,0,error)&&phase6.updateObjects(false,error)&&phase6.commitEnvironmentFrame(0,error)&&phase6.commitEnvironmentFrame(0,error)&&phase6.beginFrame(false,error,4)&&phase6.requestVisualCommand(3,error)&&phase6.beginFrame(false,error,5),"new module initializes line task while prior full-plane sampling remains displayed");exact(phase6,false,-5,-11,0,0);
 auto phase5=world(source);check(phase5.requestVisualCommand(5,error)&&phase5.beginFrame(false,error,1),"mode5 source initialization clears CPU rows without installing next pattern");exact(phase5,false,-5,-11,0,0);
 check(phase5.beginFrame(false,error,2),"mode5 pattern producer follows initial zero publication");exact(phase5,true,-5,-11,0,0);
 check(phase5.beginFrame(false,error,3),"mode5 complete pattern publishes on following frame");exact(phase5,true,-5,-11,0,0,false,0,0,true,true);
 for(unsigned n=4;n<=10;++n)check(phase5.beginFrame(false,error,n),"mode5 eight source wait updates");exact(phase5,true,-5,-11,0,0,false,0,0,true,true);
 check(phase5.requestVisualCommand(2,error)&&phase5.beginFrame(false,error,11),"mode5 accepts overlapping full-plane selector after existing worker");
 for(unsigned n=12;n<=22;++n)check(phase5.beginFrame(false,error,n),"mode5 thirteen source hidden updates");exact(phase5,false,-5,-11,0,0);
 check(phase5.beginFrame(false,error,23),"mode5 phase computes line sampling despite earlier full-plane selection");exact(phase5,false,-5,-11,0,0);check(phase5.beginFrame(false,error,24),"Main publishes the restored sampling selector");exact(phase5,true,-5,-11,0,0,false,0,0,true,true);
 std::printf("Layer publication: %u checks,0 failures; full256x224 indexed/canonical equality\n",checks);
}
void vertical(){Source source;SceneRuntime scene=world(source);check(scene.requestVisualCommand(0xfc,error),"vertical primary full scene");scene.clearMenuCursor();check(scene.fillPlaneCells(0,0,0,32,64,0,error)&&scene.fillPlaneCells(1,0,0,32,64,0,error)&&scene.fillPlaneCells(0,0,0,32,1,2,error)&&scene.fillPlaneCells(0,0,1,32,1,3,error),"distinct vertical bands");
 auto row=[&](SceneRuntime& owner,unsigned wanted){SceneImage image;check(owner.render(kSceneReferenceRGB565,image,error)&&image.indexed[0]==wanted,"displayed vertical band uses Main publication");};
 check(scene.beginFrame(false,error,1)&&scene.queueAbsolutePlanePosition(0,0,-8,error)&&scene.updateObjects(false,error),"Sub computes next vertical offset after Main");row(scene,5);NativeSaveSection saved;SceneRuntime loaded;check(SceneStateCodec::encode(scene,saved,error)&&SceneStateCodec::decode(saved,source,loaded,error),"distinct computed/displayed vertical owners restore");row(loaded,5);
 check(scene.beginFrame(true,error,2),"paused Main does not publish");row(scene,5);check(scene.beginFrame(false,error,2)&&loaded.beginFrame(false,error,2),"actual next Main publishes both restored and live offset");row(scene,6);row(loaded,6);
 auto legacy=saved;legacy.bytes[3]='R';legacy.bytes.resize(legacy.bytes.size()-6);check(SceneStateCodec::decode(legacy,source,loaded,error),"SNSR literal historical vertical image remains readable");row(loaded,6);check(loaded.beginFrame(false,error,3),"legacy acquires vertical owner at real Main boundary");row(loaded,6);
 auto invalid=saved;invalid.bytes[invalid.bytes.size()-6]=0;invalid.bytes[invalid.bytes.size()-2]=1;check(!SceneStateCodec::decode(invalid,source,loaded,error),"unknown vertical owner rejects fabricated displayed value");
 check(scene.requestVisualCommand(3,error)&&scene.beginFrame(false,error,4)&&scene.queueAbsolutePlanePosition(0,0,-16,error)&&scene.updateObjects(false,error)&&scene.beginFrame(false,error,5),"active E078 line task skips next vertical producer");row(scene,6);
 SceneRuntime retiring=world(source);retiring.clearMenuCursor();check(retiring.requestVisualCommand(0xfc,error)&&retiring.fillPlaneCells(0,0,0,32,64,0,error)&&retiring.fillPlaneCells(1,0,0,32,64,0,error)&&retiring.fillPlaneCells(0,0,0,32,1,2,error)&&retiring.fillPlaneCells(0,0,1,32,1,3,error)&&retiring.queueAbsolutePlanePosition(0,0,-8,error)&&retiring.updateObjects(false,error)&&retiring.beginFrame(false,error,1)&&retiring.requestVisualCommand(5,error)&&retiring.beginFrame(false,error,2),"mode5 starts with an actual inherited vertical publication");
 for(unsigned n=3;n<=31;++n){check(retiring.beginFrame(false,error,int(n)),"mode5 authored install/eight/thirteen/seven worker phases");if(n==3)check(retiring.queueAbsolutePlanePosition(0,0,-16,error)&&retiring.updateObjects(false,error),"held vertical successor during active line task");row(retiring,6);}
 check(retiring.beginFrame(false,error,32),"next Main after mode5 retirement publishes reset vertical owner");row(retiring,5);
}
void future(SceneRuntime& scene){for(unsigned n=9;n<17;++n){if(n==10)check(scene.requestVisualCommand(3,error),"cold new line selector");if(n==13)check(scene.requestVisualCommand(2,error)&&scene.queueScrollPosition(1,kScrollX,1,error)&&scene.updateObjects(false,error),"cold full-plane selector");if(n==15)check(scene.requestVisualCommand(0xfd,error),"cold freeze");check(scene.beginFrame(false,error,int(n)),"cold source frame");SceneImage image;check(scene.render(kSceneReferenceRGB565,image,error),"cold complete frame");std::cout.write(reinterpret_cast<const char*>(image.rgb.data()),image.rgb.size());}}
void verticalFuture(SceneRuntime& scene){for(unsigned n=0;n<8;++n){if(n==2)check(scene.queueScrollPosition(0,kScrollY,-8,error),"cold pending vertical displacement");if(n==4)check(scene.queueScrollPosition(0,kScrollY,-1,error),"cold next vertical displacement");if(n==5)check(scene.requestVisualCommand(3,error),"cold line task retains vertical publisher");check(scene.beginFrame(n==6,error,int(n+2))&&scene.updateObjects(n==6,error)&&scene.commitEnvironmentFrame(uint16_t(n+2),error),"cold separate vertical publications");SceneImage image;check(scene.render(kSceneReferenceRGB565,image,error),"cold vertical canonical raster");std::cout.write(reinterpret_cast<const char*>(image.rgb.data()),image.rgb.size());}}
}
int main(int argc,char** argv){if(argc==1){contracts();vertical();return 0;}if(argc!=2)return 2;
#ifdef _WIN32
 _setmode(_fileno(stdin),_O_BINARY);_setmode(_fileno(stdout),_O_BINARY);
#endif
 Source source;SceneRuntime scene;NativeSaveSection packet(kSaveScene);std::string flag=argv[1];bool verticalMode=flag=="--vertical-export"||flag=="--vertical-import";
 if(flag=="--export"||flag=="--vertical-export"){scene=world(source);if(verticalMode){check(scene.requestVisualCommand(0xfc,error)&&scene.beginFrame(false,error,1)&&scene.queueAbsolutePlanePosition(0,5,-8,error)&&scene.updateObjects(false,error),"cold computed successor differs from displayed vertical owner");}else check(scene.requestVisualCommand(3,error)&&scene.beginFrame(false,error,2)&&scene.requestVisualCommand(2,error)&&scene.queueScrollPosition(1,kScrollX,7,error)&&scene.updateObjects(false,error)&&scene.beginFrame(false,error,4)&&scene.requestVisualCommand(4,error),"cold actual producer snapshot");check(SceneStateCodec::encode(scene,packet,error),"cold scene encoding");uint32_t length=uint32_t(packet.bytes.size());for(int i=3;i>=0;--i)std::cout.put(char(length>>(i*8)));std::cout.write(reinterpret_cast<const char*>(packet.bytes.data()),packet.bytes.size());}
 else if(flag=="--import"||flag=="--vertical-import"){uint32_t length=0;for(unsigned i=0;i<4;++i){int c=std::cin.get();if(c<0)return 2;length=(length<<8)|uint8_t(c);}if(!length||length>1024*1024)return 2;packet.bytes.resize(length);std::cin.read(reinterpret_cast<char*>(packet.bytes.data()),length);check(bool(std::cin)&&SceneStateCodec::decode(packet,source,scene,error),"cold separate-process reconstruction");}else return 2;
 if(verticalMode)verticalFuture(scene);else future(scene);return std::cout?0:1;}
